/*
 * origami.js — client side of the procedural origami geometry.
 *
 * The folded crease pattern is generated by the server (physics/origami_domain.py)
 * so that the viewer and the unit tests always agree on the geometry.  This
 * module turns the returned vertex buffers into a three.js BufferGeometry
 * with the custom attributes the paper shader needs and provides the matte
 * paper PBR material with its crease highlight, fibre grain and the
 * layer dependent light transmission of a folded sheet.
 */

import * as THREE from "three";

export const ORIGAMI_ARCHETYPES = [
  { key: "classic_dart", label: "Classic Dart / やり飛行機", shapeFlag: 0 },
  { key: "nakamura_lock", label: "Nakamura Lock / へそ飛行機", shapeFlag: 1 },
  { key: "sky_king", label: "Sky King / 競技用グライダー", shapeFlag: 2 },
];

/**
 * Build the BufferGeometry of a folded origami mesh.
 *
 * Beside the usual attributes the geometry carries the per vertex data the
 * paper shader needs:
 *
 * - `aLayer`   number of paper layers that are stacked at that point,
 * - `aCrease`  how close the point is to a fold line (0 .. 1),
 * - `aElastic` spanwise station used by the aero-elastic bending,
 * - `aTwist`   chordwise station used by the aero-elastic twist,
 * - `aSide`    +1 when the visible side is the front of the sheet.
 */
export function buildOrigamiGeometry(payload) {
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute(
    "position",
    new THREE.Float32BufferAttribute(new Float32Array(payload.positions), 3)
  );
  geometry.setAttribute(
    "normal",
    new THREE.Float32BufferAttribute(new Float32Array(payload.normals), 3)
  );
  geometry.setAttribute(
    "uv",
    new THREE.Float32BufferAttribute(new Float32Array(payload.uvs), 2)
  );
  geometry.setAttribute(
    "aLayer",
    new THREE.Float32BufferAttribute(new Float32Array(payload.layer_counts), 1)
  );
  geometry.setAttribute(
    "aCrease",
    new THREE.Float32BufferAttribute(new Float32Array(payload.crease_weights), 1)
  );
  geometry.setAttribute(
    "aElastic",
    new THREE.Float32BufferAttribute(new Float32Array(payload.elastic_weights), 1)
  );
  geometry.setAttribute(
    "aTwist",
    new THREE.Float32BufferAttribute(new Float32Array(payload.twist_weights), 1)
  );
  geometry.setAttribute(
    "aSide",
    new THREE.Float32BufferAttribute(new Float32Array(payload.paper_sides), 1)
  );
  geometry.setIndex(
    new THREE.Uint32BufferAttribute(new Uint32Array(payload.indices), 1)
  );
  geometry.computeBoundingSphere();
  geometry.computeBoundingBox();
  return geometry;
}

/* ------------------------------------------------------------------ */
/* Paper material                                                      */
/* ------------------------------------------------------------------ */

const PAPER_COLOR = 0xf3eee2;

/**
 * Matte paper PBR material.
 *
 * The shader adds
 *
 * - a procedural fibre grain that is evaluated in object space, so the
 *   texture never stretches on the vertical keel,
 * - a crease highlight: fold lines get a soft specular edge and a slight
 *   cavity darkening, which removes the flat "plastic" look,
 * - a layer dependent light transmission: a single sheet glows when it is
 *   back lit while a four layer nose packet stays matte.
 */
export function createOrigamiMaterial() {
  const material = new THREE.MeshPhysicalMaterial({
    color: PAPER_COLOR,
    roughness: 0.82,
    metalness: 0.0,
    side: THREE.DoubleSide,
    sheen: 0.28,
    sheenRoughness: 0.85,
    sheenColor: new THREE.Color(0xfff6e6),
    emissive: new THREE.Color(0x000000),
  });

  material.userData.uniforms = {
    uFiberStrength: { value: 0.055 },
    uCreaseStrength: { value: 1.0 },
    uBackLight: { value: 0.5 },
    uBend: { value: 0.0 },
    uTwist: { value: 0.0 },
    uSemispan: { value: 0.1 },
  };

  material.onBeforeCompile = (shader) => {
    Object.assign(shader.uniforms, material.userData.uniforms);

    shader.vertexShader = shader.vertexShader
      .replace(
        "#include <common>",
        `#include <common>
        attribute float aLayer;
        attribute float aCrease;
        attribute float aElastic;
        attribute float aTwist;
        attribute float aSide;
        uniform float uBend;
        uniform float uTwist;
        uniform float uSemispan;
        varying float vLayer;
        varying float vCrease;
        varying float vSide;
        varying vec3 vPaperPos;`
      )
      .replace(
        "#include <begin_vertex>",
        `#include <begin_vertex>
        vLayer = aLayer;
        vCrease = aCrease;
        vSide = aSide;
        vPaperPos = transformed;
        // Passive aero-elasticity: the wing bends and twists with the load.
        float bend = uBend * aElastic * aElastic * uSemispan;
        float twist = uTwist * aTwist * aElastic;
        transformed.y += bend;
        transformed += normal * twist;`
      );

    shader.fragmentShader = shader.fragmentShader
      .replace(
        "#include <common>",
        `#include <common>
        uniform float uFiberStrength;
        uniform float uCreaseStrength;
        uniform float uBackLight;
        varying float vLayer;
        varying float vCrease;
        varying float vSide;
        varying vec3 vPaperPos;

        float origamiHash(vec3 p) {
          p = fract(p * 0.3183099 + vec3(0.71, 0.113, 0.419));
          p *= 17.0;
          return fract(p.x * p.y * p.z * (p.x + p.y + p.z));
        }

        float origamiNoise(vec3 x) {
          vec3 i = floor(x);
          vec3 f = fract(x);
          f = f * f * (3.0 - 2.0 * f);
          float n000 = origamiHash(i + vec3(0.0, 0.0, 0.0));
          float n100 = origamiHash(i + vec3(1.0, 0.0, 0.0));
          float n010 = origamiHash(i + vec3(0.0, 1.0, 0.0));
          float n110 = origamiHash(i + vec3(1.0, 1.0, 0.0));
          float n001 = origamiHash(i + vec3(0.0, 0.0, 1.0));
          float n101 = origamiHash(i + vec3(1.0, 0.0, 1.0));
          float n011 = origamiHash(i + vec3(0.0, 1.0, 1.0));
          float n111 = origamiHash(i + vec3(1.0, 1.0, 1.0));
          return mix(
            mix(mix(n000, n100, f.x), mix(n010, n110, f.x), f.y),
            mix(mix(n001, n101, f.x), mix(n011, n111, f.x), f.y),
            f.z
          );
        }`
      )
      .replace(
        "#include <normal_fragment_begin>",
        `#include <normal_fragment_begin>
        // Fibre grain of the paper: fine pulp noise plus long fibres.
        float grain = origamiNoise(vPaperPos * 620.0);
        float fibre = origamiNoise(vPaperPos * vec3(90.0, 1400.0, 90.0));
        vec3 grainDir = vec3(grain, fibre, origamiNoise(vPaperPos * 310.0)) - 0.5;
        normal = normalize(normal + grainDir * uFiberStrength);`
      )
      .replace(
        "#include <emissivemap_fragment>",
        `#include <emissivemap_fragment>
        // Cavity shading along the fold lines: the paper dips into the crease.
        float crease = clamp(vCrease, 0.0, 1.0) * uCreaseStrength;
        diffuseColor.rgb *= 1.0 - 0.16 * crease;
        // A single sheet of paper transmits light, a thick packet does not.
        float thin = clamp(1.0 - (vLayer - 1.0) * 0.34, 0.0, 1.0);
        float rim = pow(1.0 - abs(dot(normalize(vViewPosition), normal)), 2.5);
        totalEmissiveRadiance += diffuseColor.rgb * rim * thin * 0.22 * uBackLight;
        // A restrained highlight picks the fold lines out of the surface.
        totalEmissiveRadiance += vec3(0.055, 0.050, 0.042) * crease * rim;`
      );
  };
  material.customProgramCacheKey = () => "origami-paper-v1";
  return material;
}

/**
 * Update the aero-elastic state of the material.
 *
 * @param {THREE.Material} material
 * @param {number} bendDeg  spanwise bending (dihedral change) in degrees
 * @param {number} twistDeg chordwise twist in degrees
 * @param {number} semispan half span of the model in metres
 */
export function setOrigamiAeroelastic(material, bendDeg, twistDeg, semispan) {
  const uniforms = material && material.userData && material.userData.uniforms;
  if (!uniforms) return;
  uniforms.uBend.value = (Number(bendDeg) || 0) * (Math.PI / 180);
  uniforms.uTwist.value = (Number(twistDeg) || 0) * (Math.PI / 180);
  uniforms.uSemispan.value = Math.max(Number(semispan) || 0.1, 1e-3);
}

/* ------------------------------------------------------------------ */
/* Server access                                                       */
/* ------------------------------------------------------------------ */

/**
 * Ask the server for a folded origami mesh.
 *
 * @param {{archetype: string, alpha: number, wingspan: number,
 *          params: object, signal: AbortSignal}} options
 * @returns {Promise<object>} the mesh payload
 */
export async function requestOrigamiMesh(options) {
  const body = {
    archetype: options.archetype,
    alpha: options.alpha,
    wingspan_m: options.wingspan,
  };
  Object.assign(body, options.params || {});
  const response = await fetch("/api/v1/origami/mesh", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
    signal: options.signal,
  });
  if (!response.ok) {
    throw new Error(`origami mesh request failed with ${response.status}`);
  }
  return response.json();
}

/**
 * Ask the server for every intermediate state of a random fold programme.
 *
 * The payload carries the solid after 0, 1, 2, ... folds, so a slider can
 * walk through the folding one move at a time.
 *
 * @param {{seed: number, stepCount: number, strategy: string,
 *          signal: AbortSignal}} options
 * @returns {Promise<object>} the step states and the fold programme
 */
export async function requestOrigamiGenomeSteps(options) {
  const params = new URLSearchParams({
    seed: String(Math.round(Number(options.seed) || 0)),
    step_count: String(Math.max(1, Math.round(Number(options.stepCount) || 8))),
    strategy: String(options.strategy || "families"),
  });
  if (options.wingspan_m != null && Number(options.wingspan_m) > 0) {
    params.set("wingspan_m", String(Number(options.wingspan_m)));
  }
  const response = await fetch(`/api/v1/origami/genome/steps?${params.toString()}`, {
    signal: options.signal,
  });
  if (!response.ok) {
    throw new Error(`origami genome step request failed with ${response.status}`);
  }
  return response.json();
}

/**
 * Ask the server for the folding recipe of a random fold programme.
 *
 * @param {{seed: number, stepCount: number, strategy: string,
 *          signal: AbortSignal}} options
 * @returns {Promise<object>} the step table, the Markdown and the SVG
 */
export async function requestOrigamiRecipe(options) {
  const params = new URLSearchParams({
    seed: String(Math.round(Number(options.seed) || 0)),
    step_count: String(Math.max(1, Math.round(Number(options.stepCount) || 8))),
    strategy: String(options.strategy || "families"),
  });
  const response = await fetch(`/api/v1/origami/genome/recipe?${params.toString()}`, {
    signal: options.signal,
  });
  if (!response.ok) {
    throw new Error(`origami recipe request failed with ${response.status}`);
  }
  return response.json();
}

/**
 * Prepare a genome for the evaluation endpoint.
 *
 * ``genome_from_dict`` on the server reads the fold sense from the
 * ``fold_type`` string as if it were a boolean, so every posted fold would
 * become a mountain fold and the evaluated solid would no longer be the one
 * the viewer shows.  The client therefore sends the explicit ``mountain``
 * flag and drops the string, which makes the server fold exactly the
 * programme it was given.
 *
 * @param {object} genome the genome dictionary
 * @returns {object} the request body
 */
export function genomeEvaluationBody(genome) {
  const source = genome && typeof genome === "object" ? genome : {};
  const steps = Array.isArray(source.steps) ? source.steps : [];
  return {
    genome: {
      ...source,
      steps: steps.map((step) => {
        const copy = { ...step };
        const type = copy.fold_type;
        delete copy.fold_type;
        if (type !== undefined && type !== null) {
          copy.mountain = type !== "valley";
        } else if (copy.mountain === undefined) {
          copy.mountain = Number(copy.fold_angle_deg) >= 0;
        }
        return copy;
      }),
    },
  };
}

/**
 * Evaluate a fold programme the server did not generate itself.
 *
 * The GA research engine hands back the genome of its best individual; the
 * origami domain re-evaluates it so the viewer gets the very same geometry,
 * the centre of gravity and the grip report the unit tests use.
 *
 * @param {object} genome the genome dictionary
 * @param {{signal: AbortSignal}} options
 * @returns {Promise<object>} the genome payload (genome / geometry / grip / recipe)
 */
export async function evaluateOrigamiGenome(genome, options = {}) {
  const response = await fetch("/api/v1/origami/genome", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(genomeEvaluationBody(genome)),
    signal: options.signal,
  });
  if (!response.ok) {
    throw new Error(`origami genome evaluation failed with ${response.status}`);
  }
  return response.json();
}

/* ------------------------------------------------------------------ */
/* Crease pattern rendering                                           */
/* ------------------------------------------------------------------ */

/** A4 sheet in millimetres — the sheet the crease pattern is drawn on. */
const SHEET_WIDTH_MM = 210;
const SHEET_LENGTH_MM = 297;

/** Elements the crease pattern may use.  Everything else is dropped. */
const SVG_ALLOWED_ELEMENTS = new Set([
  "svg", "g", "line", "text", "tspan", "rect", "circle", "ellipse",
  "path", "polygon", "polyline", "defs", "marker", "title", "desc",
]);

/** Attributes the crease pattern may carry. */
const SVG_ALLOWED_ATTRIBUTES = new Set([
  "xmlns", "viewbox", "width", "height", "x", "y", "x1", "y1", "x2", "y2",
  "cx", "cy", "r", "rx", "ry", "points", "d", "transform", "class", "id",
  "data-step", "fill", "fill-opacity", "fill-rule", "stroke", "stroke-width",
  "stroke-dasharray", "stroke-linecap", "stroke-linejoin", "stroke-opacity",
  "stroke-miterlimit", "opacity", "font-family", "font-size", "font-weight",
  "text-anchor", "dominant-baseline", "vector-effect",
]);

/** Colour the server uses for a mountain fold. */
const MOUNTAIN_COLOUR = "#c02020";
/** Colour the server uses for a valley fold. */
const VALLEY_COLOUR = "#2050c0";

/**
 * Sanitise an SVG document that came from the server.
 *
 * The crease pattern is generated by our own backend, but the markup is
 * injected into the DOM, so it is treated as untrusted input: scripts, event
 * handlers, external references and unknown elements are removed before the
 * node ever reaches the document.
 *
 * @param {string} svgText the raw SVG markup
 * @returns {SVGSVGElement} the sanitised root element
 */
export function sanitizeSvg(svgText) {
  const source = String(svgText || "");
  if (!source.trim()) throw new Error("SVG が空です");
  const parsed = new DOMParser().parseFromString(source, "image/svg+xml");
  if (parsed.querySelector("parsererror")) throw new Error("SVG を解析できません");
  const root = parsed.documentElement;
  if (!root || root.nodeName.toLowerCase() !== "svg") {
    throw new Error("SVG のルート要素が <svg> ではありません");
  }
  const walk = (node) => {
    for (const child of Array.from(node.children)) {
      const tag = child.nodeName.toLowerCase();
      if (!SVG_ALLOWED_ELEMENTS.has(tag)) {
        child.remove();
        continue;
      }
      for (const attr of Array.from(child.attributes)) {
        const name = attr.name.toLowerCase();
        const value = String(attr.value || "");
        if (name.startsWith("on") || !SVG_ALLOWED_ATTRIBUTES.has(name)) {
          child.removeAttribute(attr.name);
          continue;
        }
        if (/javascript:|vbscript:|data:text\/html/i.test(value)) {
          child.removeAttribute(attr.name);
        }
      }
      walk(child);
    }
  };
  walk(root);
  return root;
}

/**
 * Format a fold angle the way the recipe shows it: a signed value with one
 * decimal, the fully flattened fold (±180°) without a sign.
 *
 * @param {number} value the signed fold angle in degrees
 * @returns {string} e.g. "+15.5°" or "180.0°"
 */
export function formatFoldAngle(value) {
  const angle = Number(value);
  if (!Number.isFinite(angle)) return "—";
  const magnitude = Math.abs(angle);
  if (magnitude >= 179.95) return `${magnitude.toFixed(1)}°`;
  return `${angle >= 0 ? "+" : "-"}${magnitude.toFixed(1)}°`;
}

/**
 * Build the crease pattern from the recipe on the client.
 *
 * Used only as a fallback when the server SVG cannot be matched to the
 * recipe steps.  The layout mirrors the server drawing (A4 sheet, 40 px
 * margin, nose up) so the two pictures agree.
 *
 * @param {Array<object>} steps the recipe steps
 * @param {object} genome the genome dictionary (for the sheet outline)
 * @returns {SVGSVGElement}
 */
function buildCreasePattern(steps, genome) {
  const margin = 40;
  const widthPx = 620;
  const scale = Math.min(
    (widthPx - 2 * margin) / SHEET_WIDTH_MM,
    (widthPx * 1.45 - 2 * margin) / SHEET_LENGTH_MM
  );
  const drawW = SHEET_WIDTH_MM * scale;
  const drawH = SHEET_LENGTH_MM * scale;
  const totalW = drawW + 2 * margin;
  const totalH = drawH + 2 * margin;
  const outline = (genome && Array.isArray(genome.sheet) && genome.sheet.length)
    ? genome.sheet
    : [[0, 0], [1, 0], [1, 1], [0, 1]];
  const toCanvas = (point) => [
    margin + point[0] * drawW,
    margin + (1 - point[1]) * drawH,
  ];
  const parts = [
    `<svg xmlns="http://www.w3.org/2000/svg" width="${totalW.toFixed(0)}" height="${totalH.toFixed(0)}" ` +
    `viewBox="0 0 ${totalW.toFixed(0)} ${totalH.toFixed(0)}" font-family="DejaVu Sans, sans-serif">`,
    `<rect x="${margin}" y="${margin}" width="${drawW.toFixed(1)}" height="${drawH.toFixed(1)}" ` +
    `fill="#fdfcf7" stroke="#202020" stroke-width="1.5"/>`,
    `<text x="${margin}" y="${margin - 12}" font-size="13" fill="#202020">` +
    `crease pattern - ${steps.length} folds</text>`,
  ];
  for (const step of steps) {
    const line = step.crease_line;
    if (!Array.isArray(line) || line.length < 2) continue;
    const [x0, y0] = toCanvas(line[0]);
    const [x1, y1] = toCanvas(line[1]);
    const mountain = step.fold_type !== "valley";
    const colour = mountain ? MOUNTAIN_COLOUR : VALLEY_COLOUR;
    const dash = mountain ? "none" : "6 4";
    const index = Number(step.step_index);
    parts.push(
      `<line data-step="${index}" x1="${x0.toFixed(1)}" y1="${y0.toFixed(1)}" ` +
      `x2="${x1.toFixed(1)}" y2="${y1.toFixed(1)}" stroke="${colour}" stroke-width="2.0" ` +
      `stroke-dasharray="${dash}"/>`
    );
    parts.push(
      `<text data-step="${index}" x="${(0.5 * (x0 + x1) + 4).toFixed(1)}" ` +
      `y="${(0.5 * (y0 + y1) - 4).toFixed(1)}" font-size="11" fill="${colour}">` +
      `${index}: ${formatFoldAngle(step.fold_angle_deg)}</text>`
    );
  }
  parts.push(
    `<text x="${margin}" y="${(totalH - 10).toFixed(1)}" font-size="11" fill="#606060">` +
    `red solid = mountain (山折り), blue dashed = valley (谷折り)</text>`
  );
  parts.push("</svg>");
  return sanitizeSvg(parts.join(""));
}

/**
 * Render the crease pattern of a fold programme.
 *
 * The server already draws the pattern; the client only *extends* it: the
 * mountain folds become solid red lines, the valley folds dashed blue ones
 * and every crease is labelled with its fold order and its signed angle.
 * Each crease carries a `data-step` attribute so the viewer can highlight
 * the crease of the step the user selected.
 *
 * @param {string} svgText the server rendered SVG
 * @param {Array<object>} steps the recipe steps
 * @param {object} genome the genome dictionary (fallback drawing)
 * @returns {SVGSVGElement}
 */
export function renderCreasePattern(svgText, steps, genome) {
  const list = Array.isArray(steps) ? steps : [];
  let root = null;
  try {
    root = sanitizeSvg(svgText);
  } catch (error) {
    root = null;
  }
  if (root) {
    const lines = Array.from(root.querySelectorAll("line"));
    const texts = Array.from(root.querySelectorAll("text"));
    // The server writes: title, one label per step, footer.
    let matched = list.length > 0 && lines.length === list.length;
    if (matched) {
      for (let index = 0; index < list.length; index += 1) {
        const label = texts[index + 1];
        if (!label || !label.textContent.trim().startsWith(`${list[index].step_index}:`)) {
          matched = false;
          break;
        }
      }
    }
    if (matched) {
      for (let index = 0; index < list.length; index += 1) {
        const step = list[index];
        const mountain = step.fold_type !== "valley";
        const colour = mountain ? MOUNTAIN_COLOUR : VALLEY_COLOUR;
        const line = lines[index];
        line.setAttribute("stroke", colour);
        line.setAttribute("stroke-width", "2.0");
        line.setAttribute("stroke-dasharray", mountain ? "none" : "6 4");
        line.setAttribute("data-step", String(step.step_index));
        const label = texts[index + 1];
        label.setAttribute("data-step", String(step.step_index));
        label.setAttribute("fill", colour);
        label.setAttribute("font-size", "11");
        label.textContent = `${step.step_index}: ${formatFoldAngle(step.fold_angle_deg)}`;
      }
      const footer = texts[list.length + 1];
      if (footer) {
        footer.textContent = "red solid = mountain (山折り), blue dashed = valley (谷折り)";
      }
      return root;
    }
  }
  return buildCreasePattern(list, genome);
}
